def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    q_s = list(map(int, data[1:n+1]))
    a_s = list(map(int, data[n+1:2*n+1]))
    b_s = list(map(int, data[2*n+1:3*n+1]))

    max_servings = 0

    for number_of_a in range(max((q_s[i] // a_s[i] if a_s[i] != 0 else float('inf')) for i in range(n)) + 1):
        min_number_of_b = float('inf')
        for j in range(n):
            if a_s[j] * number_of_a <= q_s[j]:
                remaining = q_s[j] - a_s[j] * number_of_a
                if b_s[j] != 0:
                    min_number_of_b = min(min_number_of_b, remaining // b_s[j])
            else:
                min_number_of_b = -1
                break
        if min_number_of_b >= 0:
            max_servings = max(max_servings, number_of_a + min_number_of_b)

    print(max_servings)
